#[derive(Debug, Clone)]
enum GatewayResponseAdapter {
    Passthrough {
        request_is_stream: bool,
    },
    ChatCompletions {
        stream: bool,
        requested_model: String,
        original_request_body: Vec<u8>,
    },
    Images {
        stream: bool,
        response_format: String,
        stream_prefix: String,
    },
}

impl GatewayResponseAdapter {
    fn audit_kind(&self) -> &'static str {
        match self {
            Self::Passthrough { .. } => "passthrough",
            Self::ChatCompletions { .. } => "chat_completions",
            Self::Images { stream_prefix, .. } if stream_prefix == "image_edit" => "images_edit",
            Self::Images { .. } => "images_generations",
        }
    }

    fn supports_non_stream_structured_error_fallback(&self) -> bool {
        matches!(
            self,
            Self::ChatCompletions { stream: false, .. } | Self::Images { stream: false, .. }
        )
    }
}

